"""Build the three operations product pages and share company navigation across the website."""
from pathlib import Path
import re
from site_brand import navigation, footer
DOCS=Path(__file__).resolve().parents[1]/'docs'
PRODUCTS={
'drillops.html':dict(name='EOS',tag='Daily reports / Approvals / Charges',title='A clear record<br>of every shift.',lead='Record the work, review the detail and understand the charges.',intro='EOS brings plods, approvals, production and agreed rates into one operations workspace. Keep the report and the detail behind it together.',app='eos.html',image='activities-dar.png',alt='Actual daily activity report form, shown before data entry',caption='Actual report form · shown before data entry',facts=[('For crews','Structured daily reports'),('For clients','Review and approval'),('For operations','Production and charge detail')],heading='From the shift record<br>to the agreed charges.',copy='A daily report explains more than the metres drilled. Keep the hours, crew, consumables and delays available when the work is reviewed.',steps=[('Record the shift.','Capture the rig, hole, depths, activity timeline, crew and consumables. Save a draft or submit the report when it is ready.'),('Review with context.','Approve a report, raise a query or reject it with a reason. Keep the review history with the work it describes.'),('Understand the charges.','Inspect the recorded quantities and time against contract rates. Follow the detail from the report into the charge breakdown.')],features=[('Plods and period reports','Find daily shift records and prepare reports for a selected period, project and contractor.'),('Approvals and queries','Keep review notes alongside the report so the crew can see what needs attention.'),('Production and time','Review recorded metres, operating hours and time usage for your selected program.'),('Rates and contracts','Maintain the rate library and contracts used to understand charges for the work completed.')],related='Invoice records and purchase orders belong in <a href="./accounting.html">Account</a>. Program planning and training belong in <a href="./project-management.html">Project</a>.',close='Keep the shift detail together.'),
'accounting.html':dict(name='Account',tag='Invoices / Credits / Purchase orders',title='The detail behind<br>your actual costs.',lead='A readable invoice ledger, with credits, suppliers and purchase orders close at hand.',intro='Account brings the accounting records into their own workspace. Search the ledger, inspect an invoice and follow up the records behind the work.',app='account.html',image='account-ledger.png',alt='Account invoice ledger showing its empty state without customer records',caption='Actual Account interface · empty workspace',facts=[('Invoices','Actual invoice records'),('Credits','Visible in the ledger'),('Purchasing','Purchase orders and suppliers')],heading='A ledger you can<br>read and work with.',copy='Start with the invoice record. Use the project and program context to find the relevant costs, then inspect the details and supporting information.',steps=[('Bring in the records.','Import invoice records into the accounting workspace and maintain the supplier details alongside them.'),('Read the ledger.','Search and filter invoices and credits. See the reference, supplier and value without working through a data-entry screen.'),('Check the supporting detail.','Open the invoice and review the available information. Keep purchase orders accessible in the same app.')],features=[('Actual invoices and credits','The invoice ledger focuses on actual invoice records and credits. It excludes estimated accruals.'),('Purchase orders','Find the purchasing records for your project without leaving the accounting workspace.'),('Supplier register','Maintain the full supplier list used by your accounting records.'),('Project context','Work within the selected client, project and program, using the same organisation account as EOS and Project.')],related='Recorded drilling charges and their report detail live in <a href="./drillops.html">EOS</a>. Budget allocations and program planning live in <a href="./project-management.html">Project</a>.',close='Keep the accounts in view.'),
'project-management.html':dict(name='Project',tag='Programs / Planning / People',title='Keep the program<br>in view.',lead='Bring the plan, the budget allocations and the people into one project workspace.',intro='Project gives you a dashboard of the selected program, with borehole progress, saved schedules and planning details. Move from the overview into the records behind it.',app='project.html',image='project-dashboard.png',alt='Project dashboard showing an empty workspace without customer records',caption='Actual Project interface · empty workspace',facts=[('Plan','Boreholes and schedules'),('Allocate','Program budgets'),('Prepare','Training and requirements')],heading='From the overview<br>to the next piece of work.',copy='See what has been planned, what has been recorded as complete and which planning details still need attention.',steps=[('Set up the program.','Organise the project and program, plan boreholes and record the budget allocations for the work.'),('Follow the plan.','Review borehole progress, the saved drilling timeline and planning completeness in one dashboard.'),('Prepare the people.','Use the training matrix to review recorded evidence, expiry dates and role requirements.')],features=[('Project dashboard','Review budget allocations, planned boreholes, progress and schedules for the selected program.'),('Borehole planning and maps','Keep planned holes, locations and saved scheduling details together.'),('Budget planning','Manage allocations for planned work. Allocations describe the plan; they are separate from invoice actuals.'),('Training matrix','Review the evidence and requirements for people assigned to the work, including upcoming expiry dates.')],related='Daily reports and recorded drilling charges live in <a href="./drillops.html">EOS</a>. Actual invoices and purchase orders live in <a href="./accounting.html">Account</a>.',close='Plan the work. Keep it moving.')
}
for path,p in PRODUCTS.items():
 name=p['name'];desc=re.sub('<[^>]+>','',p['lead'])
 facts=''.join(f'<div><strong>{a}</strong><span>{b}</span></div>' for a,b in p['facts'])
 steps=''.join(f'<article><span class="number">0{i} /</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(p['steps'],1))
 features=''.join(f'<article><h3>{a}</h3><p>{b}</p></article>' for a,b in p['features'])
 source=f'''<!doctype html>
<html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{name} · DrillOps</title><meta name="description" content="{desc}"><meta name="theme-color" content="#315d49">
<link rel="canonical" href="https://www.drillops.com.au/{path}"><meta property="og:title" content="{name} · DrillOps"><meta property="og:description" content="{desc}"><meta property="og:type" content="website">
<link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="./public-site.css?v=20261028"><link rel="stylesheet" href="./brand.css?v=20261108-fieldmaps1"><script defer src="./public-site.js"></script>
<script async src="https://www.googletagmanager.com/gtag/js?id=AW-18535443929"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments);}}gtag('js',new Date());gtag('config','AW-18535443929');</script>
<style>body{{margin:0}}</style></head><body class="site"><a class="skip" href="#main">Skip to content</a>{navigation(path)}
<main id="main"><section class="wrap product-hero"><div><p class="kicker">{p['tag']}</p><p class="product-title"><b>DrillOps</b> {name}</p><h1>{p['title']}</h1><p class="lead">{p['lead']}</p><p style="margin-top:18px">{p['intro']}</p><div class="actions"><a class="button" href="./{p['app']}">Open {name} ↗</a><a class="text-link" href="mailto:admin@drillops.com.au?subject={name}%20enquiry">Enquire about {name}</a></div></div><figure class="product-visual wide"><a href="./assets/products/{p['image']}" target="_blank" rel="noopener" aria-label="View full {name} screenshot"><img src="./assets/products/{p['image']}" alt="{p['alt']}" fetchpriority="high"></a><figcaption>{p['caption']}</figcaption></figure></section>
<div class="wrap facts">{facts}</div><section class="wrap section" id="workflow"><div class="section-head"><div><p class="kicker">THE WORKFLOW</p><h2>{p['heading']}</h2></div><p>{p['copy']}</p></div><div class="three-cols">{steps}</div></section>
<section class="dark-section section"><div class="wrap"><p class="kicker">IN THE WORKSPACE</p><h2>Work with the detail.</h2><div class="feature-list">{features}</div></div></section>
<section class="wrap section"><div class="section-head"><div><p class="kicker">PART OF DRILLOPS</p><h2>Focused apps.<br>A shared working context.</h2></div><div><p>{p['related']}</p><p style="margin-top:16px">EOS, Account and Project use the same organisation login and underlying project data.</p></div></div></section>
<section class="wrap closing"><div><p class="kicker">{name}</p><h2>{p['close']}</h2><p style="margin-top:14px">Sign in with the account provided by your organisation.</p></div><a class="button" href="./{p['app']}">Open {name} ↗</a></section></main>{footer()}</body></html>'''
 (DOCS/path).write_text(source+'\n')
# Keep the existing FieldOps/FieldMaps/support/legal copy and assets; share the company navigation.
for name in ['fieldops.html','fieldmaps.html','support.html','privacy.html','fieldops-support.html','fieldops-privacy.html']:
 path=DOCS/name;s=path.read_text()
 s=re.sub(r'<nav class="site-nav".*?</nav>',navigation(name),s,flags=re.S)
 s=re.sub(r'<footer class="site-footer".*?</footer>',footer(),s,flags=re.S)
 if './brand.css?' not in s:s=s.replace('</head>','<link rel="stylesheet" href="./brand.css?v=20261108-fieldmaps1"></head>')
 path.write_text(s)
